// FUNCTION: BFME2 0x00543B5A size=362 name=?update@AIGuardOuterState@@UAE?AW4StateReturnType@@XZ evidence=N:ledger tier=A
StateReturnType AIGuardOuterState::update()
{
	if (m_scanForEnemy)
	{
		m_scanForEnemy = false;
		return onEnter();
	}
	if (m_attackState == NULL)
		return STATE_SUCCESS;

	// if the position has moved (IE we're guarding an object), move with it.
	AIGuardMachine *machine = (AIGuardMachine *)getMachine();
	Object *targetToGuard = TheGameLogic->findObjectByID(machine->getTargetToGuardID());
	Team *teamToGuard = TheTeamFactory->findTeamByID(machine->getTeamToGuardID());
	if (targetToGuard)
		m_exitConditions.m_center = *targetToGuard->getPosition();
	else if (teamToGuard)
		teamToGuard->rva0039E5B9(&m_exitConditions.m_center);

	StateReturnType ret = m_attackState->update();
	Object *goal = m_attackState->getMachine()->getGoalObject();
	Object *owner = getMachineOwner();
	if (goal != NULL)
	{
		if (owner->rva0028B511() != 1 && !AI::isTargetInWeaponRange(owner, goal))
			return STATE_SUCCESS;
		if (!goal->isEffectivelyDead())
		{
			Coord3D delta;
			delta.x = m_exitConditions.m_center.x - goal->getPosition()->x;
			delta.y = m_exitConditions.m_center.y - goal->getPosition()->y;
			delta.z = m_exitConditions.m_center.z - goal->getPosition()->z;
			Real radius = AIGuardMachine::getStdGuardRange(getMachineOwner());
			if (delta.z * delta.z + delta.y * delta.y + delta.x * delta.x <= radius * radius)
				m_exitConditions.m_attackGiveUpFrame = TheAI->getAiData()->m_guardChaseUnitsDuration + TheGameLogic->getFrame();
			return ret;
		}
	}
	if (((AIGuardMachine *)getMachine())->lookForInnerTarget())
	{
		onExit(EXIT_NORMAL);
		return onEnter();
	}
	return ret;
}

// FUNCTION: BFME2 0x00543CC4 size=301 name=?onEnter@AIGuardReturnState@@UAE?AW4StateReturnType@@XZ evidence=N:ledger tier=A
StateReturnType AIGuardReturnState::onEnter()
{
	m_nextReturnScanTime = TheGameLogic->getFrame() + GetGameLogicRandomValue(0, TheAI->getAiData()->m_guardEnemyReturnScanRate, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\AI\\AIGuard.cpp", 0x371);
	m_goalPosition = ((AIGuardMachine *)getMachine())->findPositionToGuard();
	m_unk0x2C = ((AIGuardMachine *)getMachine())->getGuardRadius();

	Object *owner = getMachineOwner();
	Bool isNear = false;
	if (owner)
	{
		Coord3D delta;
		delta.set(owner->getPosition());
		delta.sub(&m_goalPosition);
		isNear = (delta.GetLengthEstimate() < 5.0f);
	}
	if (!isNear)
	{
		AIUpdateInterface *ai = getMachine()->getOwner()->getAI();
		if (ai)
		{
			if (ai->isDoingGroundMovement())
				TheAI->pathfinder()->AdjustDestination(getMachine()->getOwner(), ai->m_locomotorSet, &m_goalPosition, NULL);
			ai->destroyPath();
		}
		getMachine()->setGoalPosition(&m_goalPosition, m_unk0x2C);
		if (g_bfmeCritterDesyncLog)
		{
			void *log = theLogicRandomLogFile;
			if (log)
				fprintf(log, "CritterDesync: setAdjustDestination(TRUE) 3");
		}
		m_adjustDestinations = true;
		return AIInternalMoveToState::onEnter();
	}
	return STATE_SUCCESS;
}

// FUNCTION: BFME2 0x00543DF1 size=108 name=?update@AIGuardReturnState@@UAE?AW4StateReturnType@@XZ evidence=N:ledger tier=A
StateReturnType AIGuardReturnState::update()
{
	Object *owner = getMachine()->getOwner();
	AIUpdateInterface *ai = owner->getAI();
	if (ai != NULL && ai->getLocomotorDistanceToGoal() < AIGuardMachine::getStdGuardRange(owner))
	{
		UnsignedInt now = TheGameLogic->getFrame();
		if (now >= m_nextReturnScanTime)
		{
			m_nextReturnScanTime = now + TheAI->getAiData()->m_guardEnemyReturnScanRate;
			if (((AIGuardMachine *)getMachine())->lookForInnerTarget())
				return STATE_FAILURE;
		}
	}
	return AIInternalMoveToState::update();
}

